CustomField.formula:
IF(OR(Renewal__c, Bundled__c), 0,
  CASE(PricingMethod__c,
    'Block', IF(ISBLANK(ProratedListPrice__c),ListPrice__c * IF(ISBLANK(ProrateMultiplier__c),1, ProrateMultiplier__c),ProratedListPrice__c),
    IF(ISBLANK(ProratedListPrice__c),ListPrice__c * IF(ISBLANK(ProrateMultiplier__c),1, ProrateMultiplier__c),ProratedListPrice__c) * IF(Existing__c, Quantity__c - PriorQuantity__c, Quantity__c)
  )
)
